#!/usr/bin/env python3
"""Refresh the files Renovate cannot update itself in an update branch (#2999).

Each task is a post-upgrade command (``.github/renovate.json``) run in the branch
checkout, the current directory, and acts only on the upgrades it owns::

    python3 renovate_artifacts.py agent-cli-lock   # agent-clis-package.json -> its lock
    python3 renovate_artifacts.py constraints      # pyproject.toml, CI requirements -> constraints

``agent-cli-lock``: Renovate bumps the manifest but cannot find its lock, which
``npm install --package-lock-only`` regenerates from copies named as npm expects.
``constraints``: the command in the header of ``.github/ci/constraints.txt``
(checked by ``ci_constraints.py``) regenerates it. uv keeps the existing pins, except
each exact version Renovate proposes in ``pyproject.toml`` or a
``.github/ci/requirements-*.txt`` file, which is passed as an exact
``--upgrade-package`` request (a floor in ``pyproject.toml`` would otherwise keep the
old pin).

The branch is data. npm runs where only the two copies exist (no branch ``.npmrc``)
with ``--ignore-scripts``, and only after the manifest names exact registry
versions and the lock registry tarballs (a git or URL dependency would make npm
clone and prepare foreign code). uv runs with ``--no-build`` (no build backend),
``--no-config`` (no ``[tool.uv]``) and ``--no-sources`` (no git, path or URL
redirect). The script comes from the runner's default-branch checkout; stdlib-only.

Exit 0: done, or nothing to do. Exit 1: a tool failed, timed out or is missing, or an
input is refused; the repository file is left as it was and the message reaches the PR
as an artifact error. Exit 2: unusable data file or arguments.
"""

from __future__ import annotations

import argparse
import json
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
from collections.abc import Sequence
from pathlib import Path
from typing import Any

from renovate_data_file import Upgrade, data_file_path, load_upgrades

AGENT_CLI_MANIFEST = "src/booley/data/docker/agent-clis-package.json"
AGENT_CLI_LOCK = "src/booley/data/docker/agent-clis-package-lock.json"
CONSTRAINTS_FILE = ".github/ci/constraints.txt"
PYPROJECT = "pyproject.toml"

# What ``ci_constraints.regenerate_command`` produces: nothing else is run from a header.
_COMPILE_COMMAND = re.compile(
    r"uv pip compile pyproject\.toml --all-extras --universal"
    r" --python-version \d+\.\d+ -o \.github/ci/constraints\.txt"
)
# The CI requirements files, with the manifest, that the constraints file must agree with.
_CI_REQUIREMENTS = re.compile(r"\.github/ci/requirements-[^/]+\.txt")
# The one exact form Renovate renders for a pin, and the marks of a range.
_EXACT_PIN = re.compile(r"==\s*(?P<version>[0-9][0-9A-Za-z.+!_-]*)")
_RANGE_MARK = re.compile(r"[<>,*]|~=|!=")
# A PEP 508 project name: it lands in uv's argv, so a URL or extras form is refused.
_PROJECT_NAME = re.compile(r"[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?")
# An exact version, or an alias of one: what the agent CLI manifest holds today.
_EXACT_SPEC = re.compile(r"(npm:(@[\w.-]+/)?[\w.-]+@)?\d+\.\d+\.\d+([-+][\w.+-]*)?")
_DEPENDENCY_SECTIONS = (
    "dependencies",
    "devDependencies",
    "optionalDependencies",
    "peerDependencies",
)
_REGISTRY = "https://registry.npmjs.org/"
_HEADER_LINE = 1  # zero-based: the line after "autogenerated by uv via the following command"
_NPM_ARGUMENTS = ["install", "--package-lock-only", "--ignore-scripts", "--no-audit", "--no-fund"]
_TIMEOUT_SECONDS = 600


class ArtifactError(Exception):
    """A task cannot refresh its file; the file is left as it was (exit 1)."""


def _run_tool(argv: list[str], cwd: Path) -> None:
    """Run ``argv`` without a shell; raise ``ArtifactError`` with its stderr on failure."""
    name = argv[0]
    try:
        result = subprocess.run(
            argv,
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=_TIMEOUT_SECONDS,
            check=False,
        )
    except subprocess.TimeoutExpired as error:
        raise ArtifactError(f"{name} timed out after {_TIMEOUT_SECONDS}s") from error
    except OSError as error:
        raise ArtifactError(f"cannot run {name}: {error}") from error
    if result.returncode != 0:
        raise ArtifactError(f"{name} exited {result.returncode}:\n{result.stderr.strip()}")


def _upgrades_file(upgrades: Sequence[Upgrade], package_file: str) -> bool:
    return any(upgrade.package_file == package_file for upgrade in upgrades)


def _feeds_constraints(package_file: str) -> bool:
    """Whether an upgrade of ``package_file`` can change the constraints file."""
    return package_file == PYPROJECT or _CI_REQUIREMENTS.fullmatch(package_file) is not None


def _upgrade_requests(upgrades: Sequence[Upgrade]) -> list[str]:
    """Return the sorted ``--upgrade-package`` arguments for the exact upgrades.

    A range (a major widening in ``pyproject.toml``) names no single version and asks
    for nothing: uv resolves it from the new manifest. Anything else is refused.
    """
    requests: set[str] = set()
    for upgrade in upgrades:
        if not _feeds_constraints(upgrade.package_file):
            continue
        if _PROJECT_NAME.fullmatch(upgrade.dep_name) is None:
            raise ArtifactError(f"refusing the dependency name {upgrade.dep_name!r}")
        # Renovate keeps a space that precedes an environment marker in the value.
        exact = _EXACT_PIN.fullmatch(upgrade.new_value.strip())
        if exact is None:
            if _RANGE_MARK.search(upgrade.new_value) is None:
                raise ArtifactError(
                    f"refusing the new value {upgrade.new_value!r} of {upgrade.dep_name}"
                )
            continue
        name = re.sub(r"[-_.]+", "-", upgrade.dep_name).lower()
        requests.add(f"--upgrade-package={name}=={exact['version']}")
    return sorted(requests)


def _require_registry_only(manifest_text: str, lock_text: str) -> None:
    """Refuse a manifest or lock that makes npm fetch anything but registry packages.

    A git, URL or file dependency is cloned and its ``prepare`` scripts may run even
    under ``--ignore-scripts``; the branch must not be able to choose such a source.
    """
    try:
        manifest: Any = json.loads(manifest_text)
        lock: Any = json.loads(lock_text)
        specs = {
            name: spec
            for section in _DEPENDENCY_SECTIONS
            for name, spec in manifest.get(section, {}).items()
        }
        entries = lock.get("packages", {})
        if "overrides" in manifest or any(
            not _EXACT_SPEC.fullmatch(spec) for spec in specs.values()
        ):
            raise ValueError(
                "the manifest names a dependency that is not an exact registry version"
            )
        for path, entry in entries.items():
            if entry.get("link") or not entry.get("resolved", _REGISTRY).startswith(_REGISTRY):
                raise ValueError(f"lock entry {path!r} does not come from {_REGISTRY}")
    except (ValueError, TypeError, AttributeError) as error:
        raise ArtifactError(f"refusing the agent CLI manifest and lock: {error}") from error


def agent_cli_lock(root: Path) -> None:
    """Regenerate the agent CLI lock from the manifest by npm, in a scratch directory."""
    lock = root / AGENT_CLI_LOCK
    with tempfile.TemporaryDirectory(prefix="agent-cli-lock-") as scratch_name:
        scratch = Path(scratch_name)
        try:
            manifest_text = (root / AGENT_CLI_MANIFEST).read_text(encoding="utf-8")
            lock_text = lock.read_text(encoding="utf-8")
            _require_registry_only(manifest_text, lock_text)
            (scratch / "package.json").write_text(manifest_text, encoding="utf-8", newline="\n")
            (scratch / "package-lock.json").write_text(lock_text, encoding="utf-8", newline="\n")
        except (OSError, UnicodeDecodeError) as error:
            raise ArtifactError(f"cannot copy the agent CLI manifest and lock: {error}") from error
        _run_tool(["npm", *_NPM_ARGUMENTS], scratch)
        try:  # npm worked in scratch, so the repository lock is written only after it succeeded
            shutil.copyfile(scratch / "package-lock.json", lock)
        except OSError as error:
            raise ArtifactError(f"cannot write {AGENT_CLI_LOCK}: {error}") from error


def constraints(root: Path, upgrades: Sequence[Upgrade]) -> None:
    """Regenerate the CI constraints file with the command in its own header.

    Each exact upgrade of the branch is requested from uv, so a package that
    ``pyproject.toml`` only floors still moves to the version Renovate proposed.
    """
    try:
        lines = (root / CONSTRAINTS_FILE).read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeDecodeError) as error:
        raise ArtifactError(f"cannot read {CONSTRAINTS_FILE}: {error}") from error
    header = lines[_HEADER_LINE].removeprefix("#").strip() if len(lines) > _HEADER_LINE else ""
    if _COMPILE_COMMAND.fullmatch(header) is None:
        raise ArtifactError(
            f"{CONSTRAINTS_FILE} line {_HEADER_LINE + 1} is not the expected compile command"
        )
    requests = _upgrade_requests(upgrades)  # refused before uv runs
    # uv resolves before it writes, so a failed resolution leaves the file untouched.
    _run_tool(
        [
            *shlex.split(header),
            "--no-build",
            "--no-config",
            "--no-sources",
            *requests,
            "--custom-compile-command",
            header,
        ],
        root,
    )


def main(argv: Sequence[str] | None = None) -> int:
    """Run one task in the current directory; return the exit code."""
    parser = argparse.ArgumentParser(description="Refresh files derived from bumped manifests.")
    parser.add_argument("task", choices=["agent-cli-lock", "constraints"])
    args = parser.parse_args(argv)
    try:
        upgrades = load_upgrades(data_file_path(None))
    except ValueError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    if args.task == "agent-cli-lock":
        triggered = _upgrades_file(upgrades, AGENT_CLI_MANIFEST)
        trigger = AGENT_CLI_MANIFEST
    else:
        triggered = any(_feeds_constraints(upgrade.package_file) for upgrade in upgrades)
        trigger = f"{PYPROJECT} or the CI requirements files"
    if not triggered:
        print(f"{args.task}: no upgrade of {trigger}, nothing to do", file=sys.stderr)
        return 0
    try:
        if args.task == "agent-cli-lock":
            agent_cli_lock(Path.cwd())
        else:
            constraints(Path.cwd(), upgrades)
    except ArtifactError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    print(f"{args.task}: refreshed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
